import{_ as t,o,c as i,a2 as d}from"./chunks/framework.k0yuBbP4.js";const u=JSON.parse('{"title":"Migrating from 1.x","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://zilero232.github.io/gulp-plugins-hub/guide/migration"}]]},"headers":[],"relativePath":"guide/migration.md","filePath":"guide/migration.md","lastUpdated":1792453423000}'),r={name:"guide/migration.md"};function n(a,e,s,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="migrating-from-1-x" tabindex="-1">Migrating from 1.x <a class="header-anchor" href="#migrating-from-1-x" aria-label="Permalink to &quot;Migrating from 1.x&quot;">​</a></h1><p>2.0 rewrites every package for gulp 5 and Node.js 22.13+. The packages keep their names; the options changed where 1.x had bugs or nested everything under <code>pluginOptions</code>.</p><h2 id="everywhere" tabindex="-1">Everywhere <a class="header-anchor" href="#everywhere" aria-label="Permalink to &quot;Everywhere&quot;">​</a></h2><ul><li><strong>Node.js 22.13+</strong>, ES modules. In a CommonJS gulpfile use the named export: <code>const { scssCompiler } = require(&#39;@zilero/gulp-scss-compiler&#39;)</code>.</li><li><strong>gulp is no longer a peer dependency</strong>, as the <a href="https://github.com/gulpjs/gulp/blob/master/docs/writing-a-plugin/guidelines.md" target="_blank" rel="noreferrer">gulp guidelines</a> ask.</li><li><strong>Hooks are flat and get the file</strong>: <code>pluginOptions: { onBeforeMinify(content) }</code> became <code>onBeforeMinify({ content, file })</code>.</li><li><strong>Errors</strong> are <code>PluginError</code>s with the plugin name and file, emitted on the stream. Invalid options list every problem instead of printing a box and throwing an empty error.</li><li><strong>Files without contents</strong> (directories, <code>read: false</code>) pass through instead of failing with <code>File is null</code>.</li><li><strong>Files outside a plugin&#39;s formats pass through</strong>: the minifiers and compilers only touch their own extensions.</li><li><strong>Binary files</strong> need <code>src(globs, { encoding: false })</code> with gulp 5; image and font plugins say so when they get a file read as text.</li></ul><h2 id="package-by-package" tabindex="-1">Package by package <a class="header-anchor" href="#package-by-package" aria-label="Permalink to &quot;Package by package&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>1.x</th><th>2.0</th></tr></thead><tbody><tr><td>gulp-plugin-factory</td><td><code>GulpPluginFactory({ pluginName, onFile, onFinish })</code>; <code>undefined</code> dropped the file</td><td><code>createPlugin({ name, transform, flush })</code>; nothing returned keeps the file, <code>null</code> drops it. Plus <code>parseOptions</code>, source map and testing helpers.</td></tr><tr><td>gulp-refilename</td><td>object only</td><td>also a file name string or a function of the path parts</td></tr><tr><td>gulp-file-exclude</td><td><code>patterns</code> matched as substrings; <code>size: [min, max]</code>; <code>onExclude</code></td><td><code>patterns</code> are globs or RegExps; <code>size: { min, max }</code>; <code>exclude</code></td></tr><tr><td>gulp-conditional</td><td>the condition was checked once, for the whole stream</td><td>checked per file, conditions get the file, branches created on first use</td></tr><tr><td>gulp-folder-clone</td><td><code>onBeforeCopy</code>; files passed through unchanged</td><td>copies every file into <code>dirs</code>; <code>keepOriginal</code>, <code>onClone</code></td></tr><tr><td>gulp-archive-creator</td><td><code>format</code>, <code>archiveOptions</code>, <code>pluginOptions.archiveName</code></td><td><code>name</code> (format from its extension), <code>format</code>, <code>archiverOptions</code>, <code>emptyArchive</code>, <code>directories</code>; tgz</td></tr><tr><td>gulp-font-switcher</td><td>fontmin; <code>pluginOptions.format</code>, <code>fontOptions.glyph</code></td><td>harfbuzz subsetting and fontverter, every OpenType table kept (no native build); <code>formats</code> (several at once), <code>subset</code>, <code>hinting</code>, <code>keepOriginal</code></td></tr><tr><td>gulp-html-squeezer</td><td>html-minifier-terser, nothing minified without options</td><td>html-minifier-next, <code>preset: &#39;conservative&#39;</code> by default</td></tr><tr><td>gulp-js-squeezer</td><td><code>minifyOptions</code>, no source maps</td><td><code>terserOptions</code>, source maps chained</td></tr><tr><td>gulp-pug-compiler</td><td>rendered the file on disk, partials included</td><td>renders the contents; <code>data</code>, <code>extname</code>, <code>skipPartials</code></td></tr><tr><td>gulp-scss-compiler</td><td><code>scssOptions</code>; compiled the file on disk (<code>onBeforeCompile</code> was ignored), one process per file</td><td><code>sassOptions</code>; compiles the contents with one compiler per stream; partials skipped; source maps; <code>.sass</code></td></tr></tbody></table><p>Each plugin page ends with its own migration notes.</p><h2 id="new-in-2-0" tabindex="-1">New in 2.0 <a class="header-anchor" href="#new-in-2-0" aria-label="Permalink to &quot;New in 2.0&quot;">​</a></h2><p><a href="/gulp-plugins-hub/plugins/css-squeezer">css-squeezer</a>, <a href="/gulp-plugins-hub/plugins/image-squeezer">image-squeezer</a>, <a href="/gulp-plugins-hub/plugins/file-concat">file-concat</a>, <a href="/gulp-plugins-hub/plugins/text-replace">text-replace</a>, <a href="/gulp-plugins-hub/plugins/asset-revision">asset-revision</a> and <a href="/gulp-plugins-hub/plugins/file-changed">file-changed</a>.</p>',9)])])}const h=t(r,[["render",n]]);export{u as __pageData,h as default};
